INSERT INTO knowledge_documents (title, content, source, category, tags, isActive, createdAt, updatedAt) 
VALUES 
('مجلة الأحكام العدلية - المادة 3: شروط الواقف', 'يشترط في الواقف أن يكون حراً مكلفاً مالكاً للموقوف، فلا يصح وقف العبد ولا الصبي ولا المجنون ولا من لا يملك الموقوف.', 'مجلة الأحكام العدلية', 'reference', 'شروط الواقف، الأهلية، الملكية', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573)),
('مجلة الأحكام العدلية - المادة 6: استبدال الوقف', 'لا يجوز استبدال الوقف إلا إذا تعطلت منافعه بالكلية، أو كان في الاستبدال مصلحة ظاهرة للوقف، وبإذن القاضي.', 'مجلة الأحكام العدلية', 'reference', 'استبدال الوقف، المصلحة، القاضي', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573)),
('قانون الأوقاف الأردني - المادة 2: تعريف الوقف الخيري', 'الوقف الخيري هو ما وقف على جهة بر وخير ابتداءً كالمساجد والمدارس والمستشفيات ودور الأيتام.', 'قانون الأوقاف الأردني رقم 23 لسنة 1964', 'law', 'الوقف الخيري، جهات البر، المساجد', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573)),
('قانون الأوقاف الأردني - المادة 3: الوقف الذري', 'الوقف الذري هو ما وقف على الذرية ابتداءً ثم على جهة بر وخير انتهاءً.', 'قانون الأوقاف الأردني رقم 23 لسنة 1964', 'law', 'الوقف الذري، الذرية، الوقف الأهلي', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573)),
('قانون الأوقاف الأردني - المادة 15: صلاحيات المتولي', 'للمتولي إدارة الوقف وتأجير أعيانه واستثمارها بما يحقق مصلحة الوقف، وله أن يقاضي ويقاضى باسم الوقف.', 'قانون الأوقاف الأردني رقم 23 لسنة 1964', 'law', 'المتولي، الإدارة، التأجير', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573)),
('قانون الأوقاف الأردني - المادة 20: الإشراف على الأوقاف', 'تشرف وزارة الأوقاف على جميع الأوقاف الخيرية والذرية، ولها حق الرقابة والتفتيش على أعمال المتولين.', 'قانون الأوقاف الأردني رقم 23 لسنة 1964', 'law', 'وزارة الأوقاف، الإشراف، الرقابة', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573)),
('قرار بقانون رقم 1 لسنة 2018 - المادة 2: أهداف الوزارة', 'تهدف وزارة الأوقاف والشؤون الدينية إلى إدارة وتنظيم الأوقاف الإسلامية وحمايتها وتنميتها واستثمارها.', 'قرار بقانون رقم (1) لسنة 2018 بشأن الأوقاف الإسلامية', 'law', 'وزارة الأوقاف، الأهداف، الإدارة', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573)),
('قرار بقانون 2018 - المادة 5: المجلس الأعلى للأوقاف', 'يشكل مجلس أعلى للأوقاف برئاسة الوزير وعضوية ممثلين عن الجهات ذات العلاقة، ويختص بوضع السياسات العامة للأوقاف.', 'قرار بقانون رقم (1) لسنة 2018', 'law', 'المجلس الأعلى، السياسات، الوزير', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573)),
('قرار بقانون 2018 - المادة 10: حماية الأوقاف', 'تتمتع الأوقاف بالحماية القانونية، ولا يجوز الاعتداء عليها أو الاستيلاء عليها أو تغيير معالمها.', 'قرار بقانون رقم (1) لسنة 2018', 'law', 'حماية الأوقاف، الاعتداء، الاستيلاء', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573)),
('الفقه الحنفي - تعريف الوقف', 'الوقف في الفقه الحنفي هو حبس العين على ملك الواقف والتصدق بالمنفعة. فالعين تبقى على ملك الواقف، والمنفعة تصرف في الجهة الموقوف عليها.', 'الفقه الحنفي - كتاب الوقف', 'jurisprudence', 'الفقه الحنفي، تعريف الوقف، حبس العين', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573));